#!/usr/bin/env bun
/**
 * chisme CLI entry point and command dispatch.
 *
 * Local search and viewer for AI coding sessions captured as Entire checkpoints.
 * Keyword search always works; semantic search is enabled when sqlite-vec and the
 * embedding model are available, and degrades gracefully otherwise.
 */
import { Database } from "bun:sqlite";
import { isEmbedderInstalled } from "@chisme/core";
import { loadVecExtension } from "./runtime/vec.ts";
import { colors } from "./cli/colors.ts";
import { cmdSearch } from "./commands/search.ts";
import { cmdSync } from "./commands/sync.ts";
import { cmdList } from "./commands/list.ts";
import { cmdStatus } from "./commands/status.ts";
import { cmdAgent } from "./commands/agent.ts";

// Replaced at build time via `--define BUILD_VERSION`; falls back in dev.
declare const BUILD_VERSION: string | undefined;
const VERSION = typeof BUILD_VERSION !== "undefined" ? BUILD_VERSION : "0.1.0-dev";

const USAGE = `chisme ${VERSION} - local search for AI coding sessions

Usage: chisme <command> [options]

Commands:
  search [query]    Search indexed checkpoints (hybrid local search)
  index             Fetch latest checkpoints and rebuild the local index
  sync              Alias for index
  status            Show index and environment status
  list              List recent checkpoints
  agent install     Write the Claude Code search subagent (.claude/agents)
  help [command]    Show help
  version           Show version and capabilities

Run 'chisme <command> --help' for command-specific flags.`;

async function cmdVersion(): Promise<void> {
  const db = new Database(":memory:");
  const vec = await loadVecExtension(db);
  db.close();
  const embedder = await isEmbedderInstalled();
  console.log(`chisme ${VERSION}`);
  console.log(`bun ${Bun.version}`);
  console.log(`platform ${process.platform}-${process.arch}`);
  console.log(
    `semantic search: ${
      vec.available
        ? `${embedder ? "available" : "storage only (embedder not installed)"} (sqlite-vec ${vec.version}, ${vec.source})`
        : "unavailable (keyword-only)"
    }`,
  );
}

function helpFor(command: string | undefined): string[] {
  switch (command) {
    case "search":
      return ["search", "--help"];
    case "index":
    case "sync":
      return ["--help"];
    case "list":
      return ["--help"];
    case "agent":
      return ["--help"];
    default:
      return [];
  }
}

async function main(): Promise<void> {
  const argv = process.argv.slice(2);
  const command = argv[0] ?? "help";
  const rest = argv.slice(1);

  switch (command) {
    case "version":
    case "--version":
    case "-v":
      await cmdVersion();
      return;
    case "help":
    case "--help":
    case "-h": {
      // `chisme help <command>` delegates to that command's own help.
      const target = rest[0];
      if (!target) {
        console.log(USAGE);
        return;
      }
      const forwarded = helpFor(target);
      if (forwarded.length === 0) {
        console.log(USAGE);
        return;
      }
      await dispatch(target, forwarded.slice(target === "search" ? 1 : 0));
      return;
    }
    case "search":
    case "index":
    case "sync":
    case "list":
    case "status":
    case "agent":
      await dispatch(command, rest);
      return;
    default:
      console.error(`chisme: unknown command '${command}'. Run 'chisme help'.`);
      process.exit(1);
  }
}

async function dispatch(command: string, rest: string[]): Promise<void> {
  switch (command) {
    case "search":
      return cmdSearch(rest);
    case "index":
    case "sync":
      return cmdSync(rest);
    case "list":
      return cmdList(rest);
    case "status":
      return cmdStatus(VERSION);
    case "agent":
      return cmdAgent(rest);
  }
}

main().catch((error: unknown) => {
  console.error(`${colors.red("chisme:")} ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
});

/**
 * Argument parsing for the chisme CLI.
 *
 * Wraps Node's built-in `util.parseArgs` (available in Bun) and adds the inline
 * filter parser: `author:`, `date:`, `branch:`, and `repo:` embedded in the query
 * string, with optional quoted values. Explicit flags take precedence over inline
 * filters when both are present.
 */
import { parseArgs, type ParseArgsConfig } from "node:util";

export interface InlineFilters {
  text: string;
  author?: string;
  branch?: string;
  date?: string;
  repo?: string;
}

const INLINE = /\b(author|date|branch|repo):("([^"]*)"|'([^']*)'|(\S+))/gi;

/** Pulls `key:value` filters out of a query string, returning them and the rest. */
export function parseInlineFilters(query: string): InlineFilters {
  const filters: InlineFilters = { text: "" };
  const stripped = query.replace(INLINE, (_m, key: string, _v, dq, sq, bare) => {
    const value = dq ?? sq ?? bare ?? "";
    (filters as Record<string, string>)[key.toLowerCase()] = value;
    return " ";
  });
  filters.text = stripped.replace(/\s+/g, " ").trim();
  return filters;
}

function toInt(value: string | undefined, fallback: number): number {
  if (value == null) return fallback;
  const n = Number.parseInt(value, 10);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

function coerceDate(value: string | undefined): "week" | "month" | undefined {
  return value === "week" || value === "month" ? value : undefined;
}

export interface SearchArgs {
  query: string;
  json: boolean;
  limit: number;
  page: number;
  author?: string;
  branch?: string;
  date?: "week" | "month";
  repo?: string;
  semantic: boolean;
  help: boolean;
}

function parse(argv: string[], options: ParseArgsConfig["options"]) {
  return parseArgs({ args: argv, options, allowPositionals: true, strict: true });
}

export function parseSearchArgs(argv: string[]): SearchArgs {
  const { values, positionals } = parse(argv, {
    json: { type: "boolean" },
    limit: { type: "string" },
    page: { type: "string" },
    author: { type: "string" },
    branch: { type: "string" },
    date: { type: "string" },
    repo: { type: "string" },
    semantic: { type: "boolean" },
    "no-semantic": { type: "boolean" },
    help: { type: "boolean", short: "h" },
  });

  const inline = parseInlineFilters(positionals.join(" "));

  return {
    query: inline.text,
    json: Boolean(values.json),
    limit: toInt(values.limit as string | undefined, 25),
    page: toInt(values.page as string | undefined, 1),
    author: (values.author as string | undefined) ?? inline.author,
    branch: (values.branch as string | undefined) ?? inline.branch,
    date: coerceDate((values.date as string | undefined) ?? inline.date),
    repo: (values.repo as string | undefined) ?? inline.repo,
    semantic: values["no-semantic"] ? false : true,
    help: Boolean(values.help),
  };
}

export interface SyncArgs {
  full: boolean;
  remote: string;
  help: boolean;
}

export function parseSyncArgs(argv: string[]): SyncArgs {
  const { values } = parse(argv, {
    full: { type: "boolean" },
    remote: { type: "string" },
    help: { type: "boolean", short: "h" },
  });
  return {
    full: Boolean(values.full),
    remote: (values.remote as string | undefined) ?? "origin",
    help: Boolean(values.help),
  };
}

export interface ListArgs {
  repo?: string;
  limit: number;
  json: boolean;
  help: boolean;
}

export function parseListArgs(argv: string[]): ListArgs {
  const { values } = parse(argv, {
    repo: { type: "string" },
    limit: { type: "string" },
    json: { type: "boolean" },
    help: { type: "boolean", short: "h" },
  });
  return {
    repo: values.repo as string | undefined,
    limit: toInt(values.limit as string | undefined, 25),
    json: Boolean(values.json),
    help: Boolean(values.help),
  };
}

