1	/**
2	 * Resolves where chisme stores its global, multi-repo index.
3	 *
4	 * Follows the XDG Base Directory spec on Linux/macOS, falling back to sensible
5	 * per-platform defaults. Honors CHISME_DATA_DIR for tests and power users.
6	 */
7	import { homedir } from "node:os";
8	import { join } from "node:path";
9	import { mkdirSync } from "node:fs";
10	
11	/** Root directory for chisme's persistent data (the SQLite index lives here). */
12	export function dataDir(): string {
13	  const override = process.env.CHISME_DATA_DIR;
14	  if (override) return override;
15	
16	  const xdg = process.env.XDG_DATA_HOME;
17	  if (xdg) return join(xdg, "chisme");
