196	export function clearRepo(db: Database, repoId: number, vecAvailable: boolean): void {
197	  const run = db.transaction(() => {
198	    const pks = db
199	      .query("SELECT id FROM checkpoints WHERE repo_id = ?")
200	      .all(repoId) as { id: number }[];
201	    for (const { id } of pks) {
