const tryEmbed = opts.vecAvailable && opts.embeddings !== false;
const embedFn = opts.embedder?.embed ?? embed;
const concurrency = Math.max(1, opts.embedder?.concurrency ?? 1);
let synced = 0;
let failed = 0;
let processed = 0;
let embedderUsed = false;

// Process in chunks of `concurrency`: read inputs (sequential git I/O), embed
// the chunk in parallel (a pool runs up to `concurrency` at once), then upsert.
for (let i = 0; i < newIds.length; i += concurrency) {
  const chunk = newIds.slice(i, i + concurrency);
  const inputs = chunk.map((id) => {
    try {
      const raw = readCheckpoint(root, ref, id);
      return raw ? buildInput(root, repo.id, raw) : null;
    } catch {
      return null;
    }
  });

  if (tryEmbed) {
    const vectors = await Promise.all(
      inputs.map((inp) => (inp ? embedFn(embedText(inp)) : Promise.resolve(null))),
    );
    vectors.forEach((vector, j) => {
      const inp = inputs[j];
      if (vector && inp) {
        inp.embedding = vector;
        embedderUsed = true;
      }
    });
  }

  for (const inp of inputs) {
    if (!inp) {
      failed++;
    } else {
      try {
        upsertCheckpoint(opts.db, inp, opts.vecAvailable);
        synced++;
      } catch {
        failed++;
      }
    }
    processed++;
    opts.onProgress?.(processed, newIds.length);
  }
}

