/**
 * Embedding worker for the index pool (compiled-binary path only).
 *
 * Runs in a Bun Worker. On `init` it configures the WASM embedder with the paths
 * the main thread extracted and warms the model; then it answers `embed` requests.
 *
 * It must be added to the binary as an explicit `bun build --compile` entrypoint
 * (see apps/cli/build.ts) and is referenced by the pool as
 * `new Worker("./embed-worker.ts")` (a bare relative specifier, the form Bun maps
 * to the bundled worker; the `new URL(..., import.meta.url)` form hangs).
 */
import { configureEmbedder, embed } from "@chisme/core";

declare const self: {
  onmessage: ((e: MessageEvent) => void) | null;
  postMessage(message: unknown, transfer?: Transferable[]): void;
};

interface InitMessage {
  type: "init";
  wasmPaths: { wasm: string; mjs: string };
  cacheDir: string;
}
interface EmbedMessage {
  type: "embed";
  id: number;
  text: string;
}

self.onmessage = async (event: MessageEvent) => {
  const message = event.data as InitMessage | EmbedMessage;

  if (message.type === "init") {
    configureEmbedder({ forceWebBackend: true, wasmPaths: message.wasmPaths, cacheDir: message.cacheDir });
    await embed("warm up"); // load the model before real work
    self.postMessage({ type: "ready" });
    return;
  }

  const vector = await embed(message.text);
  if (vector) self.postMessage({ type: "result", id: message.id, vector }, [vector.buffer]);
  else self.postMessage({ type: "result", id: message.id, vector: null });
};

