/**
 * A small pool of Bun Workers that embed text in parallel.
 *
 * Speeds up indexing in the compiled binary, where the WASM backend is
 * single-threaded and Bun cannot run onnxruntime-web's own thread pool. The pool
 * is capped conservatively (see embedderPoolSize in runtime/embedder.ts):
 * oversubscription degrades throughput badly, so it tops out at 2 workers.
 *
 * Each `embed` call is queued and dispatched to the next free worker; results
 * resolve the matching promise. Worker vectors are transferred (zero-copy).
 */
interface Pending {
  resolve(vector: Float32Array | null): void;
}

export interface PoolOptions {
  wasmPaths: { wasm: string; mjs: string };
  cacheDir: string;
}

export class EmbedderPool {
  private readonly workers: Worker[] = [];
  private readonly free: Worker[] = [];
  private readonly queue: { text: string; pending: Pending }[] = [];
  private readonly pending = new Map<number, Pending>();
  private nextId = 0;
  private readonly readyAll: Promise<void>;

