/**
 * Wires up the WASM embedder backend when running as a compiled binary.
 *
 * In dev this is a no-op: `embedderAssets` is null and the embedder uses the
 * native onnxruntime-node backend. In a compiled binary, we extract the embedded
 * onnxruntime-web WASM binary and its mjs loader to the data dir, then tell core's
 * embedder to force the WASM backend and load from those paths.
 *
 * For indexing throughput, the binary can also run a small worker pool
 * (`createIndexEmbedderPool`), since the WASM backend is single-threaded. The pool
 * is capped conservatively because oversubscription degrades it badly. Never
 * throws; on failure the embedder stays inline (or unavailable) and search/index
 * degrade gracefully.
 */
import { join } from "node:path";
import { mkdirSync, writeFileSync, existsSync } from "node:fs";
import { availableParallelism } from "node:os";
import { configureEmbedder, dataDir, embed, modelCacheDir } from "@chisme/core";
import { embedderAssets } from "../embedded/embedder-assets.ts";
import { EmbedderPool } from "./embedder-pool.ts";

let wasmPaths: { wasm: string; mjs: string } | null = null;

/** Extracts the embedded WASM once and returns its `file://` paths (null in dev). */
async function ensureExtracted(): Promise<{ wasm: string; mjs: string } | null> {
  if (!embedderAssets) return null;
  if (wasmPaths) return wasmPaths;
  try {
    const dir = join(dataDir(), "runtime");
    mkdirSync(dir, { recursive: true });
    const wasmPath = join(dir, "ort-wasm-simd-threaded.wasm");
    const mjsPath = join(dir, "ort-wasm-simd-threaded.mjs");
    if (!existsSync(wasmPath)) {
      writeFileSync(wasmPath, new Uint8Array(await Bun.file(embedderAssets.wasm).arrayBuffer()));
    }
    if (!existsSync(mjsPath)) {
      writeFileSync(mjsPath, new Uint8Array(await Bun.file(embedderAssets.loader).arrayBuffer()));
    }
    wasmPaths = { wasm: `file://${wasmPath}`, mjs: `file://${mjsPath}` };
    return wasmPaths;
  } catch {
    return null;
  }
}

/** Configures the inline embedder (used by search and as the index fallback). */
export async function setupEmbedder(): Promise<void> {
  const paths = await ensureExtracted();
  if (paths) configureEmbedder({ forceWebBackend: true, wasmPaths: paths });
}

/**
 * Conservative pool size: only pool on >= 4 cores, capped at 2. Beyond 2 the
 * single-threaded WASM inferences contend and throughput drops (measured).
 */
function embedderPoolSize(): number {
  let cores = 1;
  try {
    cores = availableParallelism();
  } catch {
    cores = 1;
  }
  return Math.max(1, Math.min(2, Math.floor(cores / 2)));
}

/**
 * Creates a worker pool to parallelize indexing in the binary. Returns null in dev
 * (native backend) or on machines too small to benefit. The caller must `close()`
 * the pool when done.
 */
export async function createIndexEmbedderPool(): Promise<EmbedderPool | null> {
  const paths = await ensureExtracted();
  if (!paths) return null; // dev: native backend already multi-threaded
  const size = embedderPoolSize();
  if (size < 2) return null; // not enough cores to bother

  try {
    configureEmbedder({ forceWebBackend: true, wasmPaths: paths });
    // Warm the model cache on this thread first so the workers load from cache
    // instead of racing to download it concurrently into the same dir.
    await embed("warm up");
    const pool = new EmbedderPool(size, { wasmPaths: paths, cacheDir: modelCacheDir() });
    await pool.ready();
    return pool;
  } catch {
    return null;
  }
}

