1	/**
2	 * Team-aware incremental indexing of one repo's checkpoints (PLAN.md Section 6).
3	 *
4	 * Resolves the repo identity, fetches teammates' checkpoints (best effort),
5	 * resolves the ref to read, scans checkpoint ids, diffs against what is already
6	 * indexed, and indexes only the new ones. `full` wipes the repo's rows first.
7	 * Embeddings are attempted only when vec storage is available; failure to embed a
8	 * checkpoint degrades it to keyword-only without failing the sync.
9	 */
10	import type { Database } from "bun:sqlite";
11	import type { RawCheckpoint } from "../types.ts";
12	import {
13	  findCommitByCheckpointId,
14	  getCommitInfo,
15	  getDiffStats,
16	  gitRoot,
17	  fetchCheckpoints,
18	  repoSlug,
19	  resolveCheckpointsRef,
20	} from "../git/repo.ts";
21	import { readCheckpoint, scanCheckpointIds, scanCheckpointIdsByRecency } from "../git/checkpoints.ts";
22	import { extractPlainText } from "../parser/transcript.ts";
23	import { upsertRepo, setLastSync } from "../db/repos.ts";
24	import { clearRepo, knownCheckpointIds, upsertCheckpoint, type CheckpointInput } from "../db/checkpoints.ts";
25	import { embed } from "../embeddings/embedder.ts";
26	
27	export interface SyncOptions {
28	  cwd: string;
29	  db: Database;
30	  vecAvailable: boolean;
31	  full?: boolean;
32	  remote?: string;
33	  /** Index only the newest N checkpoints (by branch commit recency). */
34	  limit?: number;
35	  /** Attempt embeddings when vec storage is available (default true). */
36	  embeddings?: boolean;
37	  onProgress?: (done: number, total: number) => void;
38	}
39	
40	export interface SyncResult {
41	  slug: string;
42	  ref: string | null;
43	  synced: number;
44	  skipped: number;
45	  failed: number;
46	  durationMs: number;
47	  /** Total checkpoints present on the ref. */
48	  total: number;
49	  /** True when no checkpoints branch/ref exists for this repo. */
50	  noCheckpoints: boolean;
51	  /** True if at least one checkpoint was embedded. */
52	  embedderUsed: boolean;
53	}
54	
55	/** Normalizes a timestamp to ISO, or returns null when unparseable. */
56	function normalizeDate(raw: string | undefined | null): string | null {
57	  if (!raw) return null;
58	  const t = Date.parse(raw);
59	  return Number.isNaN(t) ? raw : new Date(t).toISOString();
60	}
61	
62	/** Joins the fields we embed, truncated so the model stays fast. */
63	function embedText(input: CheckpointInput): string {
64	  return [input.prompt, input.summary, input.commitMessage ?? "", input.filesTouched.join(" ")]
65	    .filter(Boolean)
66	    .join("\n")
67	    .slice(0, 1500);
68	}
69	
70	/** Builds a checkpoint row from raw git data plus the linked commit, if any. */
71	function buildInput(root: string, repoId: number, raw: RawCheckpoint): CheckpointInput {
72	  const firstSession = raw.sessions[0];
73	  const commitSha = findCommitByCheckpointId(root, raw.id);
74	  const commit = commitSha ? getCommitInfo(root, commitSha) : null;
75	  const diff = commitSha ? getDiffStats(root, commitSha) : null;
76	
77	  const branch = raw.summary.branch ?? firstSession?.metadata.branch ?? null;
78	  const tokens = raw.summary.token_usage ?? firstSession?.metadata.token_usage ?? {};
79	  const createdAt =
80	    normalizeDate(firstSession?.metadata.created_at) ??
81	    normalizeDate(raw.summary.created_at) ??
82	    normalizeDate(commit?.date);
83	
84	  const transcriptText = raw.sessions
85	    .map((s) => extractPlainText(s.transcriptJsonl))
86	    .filter(Boolean)
87	    .join("\n");
88	
89	  return {
90	    repoId,
91	    checkpointId: raw.id,
92	    branch,
93	    commitSha,
94	    commitMessage: commit?.subject ?? null,
95	    author: commit?.author ?? null,
96	    authorEmail: commit?.email ?? null,
97	    createdAt,
98	    filesTouched: raw.summary.files_touched ?? [],
99	    strategy: raw.summary.strategy ?? firstSession?.metadata.strategy ?? null,
100	    inputTokens: tokens.input_tokens ?? null,
101	    outputTokens: tokens.output_tokens ?? null,
102	    additions: diff?.additions ?? null,
103	    deletions: diff?.deletions ?? null,
104	    prompt: firstSession?.prompt ?? "",
105	    summary: firstSession?.metadata.summary?.text ?? "",
106	    transcriptText,
107	    embedding: null,
108	  };
109	}
110	
111	export async function syncRepo(opts: SyncOptions): Promise<SyncResult> {
112	  const started = Date.now();
113	  const remote = opts.remote ?? "origin";
114	  const root = gitRoot(opts.cwd);
115	  if (!root) throw new Error("not a git repository (run chisme index from inside a repo)");
116	
117	  const { slug, remoteUrl } = repoSlug(root, remote);
118	  const repo = upsertRepo(opts.db, slug, remoteUrl, root);
119	
120	  // Best effort: pick up teammates' pushed checkpoints. Ignore failure.
121	  if (remoteUrl) fetchCheckpoints(root, remote);
122	
123	  const ref = resolveCheckpointsRef(root, remote);
124	  if (!ref) {
125	    return {
126	      slug,
127	      ref: null,
128	      synced: 0,
129	      skipped: 0,
130	      failed: 0,
131	      durationMs: Date.now() - started,
132	      total: 0,
133	      noCheckpoints: true,
134	      embedderUsed: false,
135	    };
136	  }
137	
138	  // Recency order only when limiting (newest N); otherwise the cheaper tree scan.
139	  const ids = opts.limit != null ? scanCheckpointIdsByRecency(root, ref) : scanCheckpointIds(root, ref);
140	  if (opts.full) clearRepo(opts.db, repo.id, opts.vecAvailable);
141	  const known = opts.full ? new Set<string>() : knownCheckpointIds(opts.db, repo.id);
142	  let newIds = ids.filter((id) => !known.has(id));
143	  if (opts.limit != null) newIds = newIds.slice(0, opts.limit);
144	
145	  const tryEmbed = opts.vecAvailable && opts.embeddings !== false;
146	  let synced = 0;
147	  let failed = 0;
148	  let embedderUsed = false;
149	
150	  for (const id of newIds) {
151	    try {
152	      const raw = readCheckpoint(root, ref, id);
153	      if (!raw) {
154	        failed++;
155	        continue;
156	      }
157	      const input = buildInput(root, repo.id, raw);
158	      if (tryEmbed) {
159	        const vector = await embed(embedText(input));
160	        if (vector) {
161	          input.embedding = vector;
162	          embedderUsed = true;
163	        }
164	      }
165	      upsertCheckpoint(opts.db, input, opts.vecAvailable);
166	      synced++;
167	    } catch {
168	      failed++;
169	    }
170	    opts.onProgress?.(synced + failed, newIds.length);
171	  }
172	
173	  setLastSync(opts.db, repo.id, new Date().toISOString());
174	
175	  return {
176	    slug,
177	    ref,
178	    synced,
179	    skipped: ids.length - newIds.length,
180	    failed,
181	    durationMs: Date.now() - started,
182	    total: ids.length,
183	    noCheckpoints: false,
184	    embedderUsed,
185	  };
186	}

